export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type FailedAt = Provider | "repository";
type AbortClassification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

interface ShipmentFields {
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}

interface QueuedShipment extends ShipmentFields {
  state: "queued";
}

interface DispatchedShipment extends ShipmentFields {
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}

interface DeferredShipment extends ShipmentFields {
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: Refusal[];
}

interface UnavailableShipment extends ShipmentFields {
  state: "unavailable";
  rejections: Refusal[];
}

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

interface Refusal {
  provider: Provider;
  reason: RefusalReason;
}

interface AbortBody {
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: FailedAt;
  classification: AbortClassification;
  rejections: Refusal[];
}

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

export interface ServiceResponse {
  status: number;
  body:
    | PublicShipment
    | AbortBody
    | {
        code: "invalid_command" | "not_found" | "service_unavailable";
      };
}

type Command =
  | { op: "get"; shipmentId: string }
  | { op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient };

type CarrierOutcome =
  | { kind: "confirmed"; bookingId: string }
  | { kind: "refused"; refusal: Refusal }
  | { kind: "throttled"; provider: Provider; retryAtMs: number }
  | { kind: "aborted"; failedAt: Provider; classification: Exclude<AbortClassification, "repository_failure"> };

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function isValidRetryAtMs(value: unknown, nowMs: number): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > nowMs;
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function cloneRejections(rejections: Refusal[]): Refusal[] {
  return rejections.map((rejection) => ({
    provider: rejection.provider,
    reason: rejection.reason,
  }));
}

function baseFields(shipment: StoredShipment) {
  return {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = baseFields(shipment);
  if (shipment.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (shipment.state === "dispatched") {
    return {
      ...fields,
      state: "dispatched",
      provider: shipment.provider,
      bookingId: shipment.bookingId,
      dispatchedAtMs: shipment.dispatchedAtMs,
    };
  }
  if (shipment.state === "deferred") {
    return {
      ...fields,
      state: "deferred",
      nextProvider: shipment.nextProvider,
      retryAtMs: shipment.retryAtMs,
      rejections: cloneRejections(shipment.rejections),
    };
  }
  return {
    ...fields,
    state: "unavailable",
    rejections: cloneRejections(shipment.rejections),
  };
}

function dispatchStatus(shipment: StoredShipment): number {
  if (shipment.state === "dispatched") {
    return 200;
  }
  if (shipment.state === "deferred") {
    return 202;
  }
  if (shipment.state === "unavailable") {
    return 422;
  }
  return 200;
}

function abortResponse(
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: Refusal[],
): ServiceResponse {
  return {
    status: 500,
    body: {
      code: "dispatch_aborted",
      shipmentId,
      failedAt,
      classification,
      rejections: cloneRejections(rejections),
    },
  };
}

function emitAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: Refusal[],
) {
  dependencies.logger.info({
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections: cloneRejections(rejections),
  });
}

function parseAtlasRejection(value: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(value) || typeof value.code !== "string") {
    return { kind: "aborted", failedAt: "atlas", classification: "unknown_failure" };
  }
  if (value.code === "cannot_ship") {
    if (!isRefusalReason(value.reason)) {
      return { kind: "aborted", failedAt: "atlas", classification: "invalid_provider_response" };
    }
    return {
      kind: "refused",
      refusal: { provider: "atlas", reason: value.reason },
    };
  }
  if (value.code === "rate_limited") {
    if (!isValidRetryAtMs(value.retryAtMs, nowMs)) {
      return { kind: "aborted", failedAt: "atlas", classification: "invalid_provider_response" };
    }
    return { kind: "throttled", provider: "atlas", retryAtMs: value.retryAtMs };
  }
  return { kind: "aborted", failedAt: "atlas", classification: "unknown_failure" };
}

function parseBeaconRejection(value: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(value) || typeof value.type !== "string") {
    return { kind: "aborted", failedAt: "beacon", classification: "unknown_failure" };
  }
  if (value.type === "rejected") {
    if (!isObject(value.details) || !isRefusalReason(value.details.reason)) {
      return { kind: "aborted", failedAt: "beacon", classification: "invalid_provider_response" };
    }
    return {
      kind: "refused",
      refusal: { provider: "beacon", reason: value.details.reason },
    };
  }
  if (value.type === "throttled") {
    if (!isObject(value.details) || !isValidRetryAtMs(value.details.retryAtMs, nowMs)) {
      return { kind: "aborted", failedAt: "beacon", classification: "invalid_provider_response" };
    }
    return { kind: "throttled", provider: "beacon", retryAtMs: value.details.retryAtMs };
  }
  return { kind: "aborted", failedAt: "beacon", classification: "unknown_failure" };
}

async function attemptCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<CarrierOutcome> {
  try {
    const confirmation =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
    if (!isObject(confirmation)) {
      return { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
    }
    const identifier = provider === "atlas" ? confirmation.bookingId : confirmation.reference;
    if (typeof identifier !== "string" || identifier.length === 0) {
      return { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
    }
    return { kind: "confirmed", bookingId: identifier };
  } catch (rejection) {
    return provider === "atlas"
      ? parseAtlasRejection(rejection, nowMs)
      : parseBeaconRejection(rejection, nowMs);
  }
}

function makeProviderRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function nextUnrefusedProvider(rejections: Refusal[]): Provider | undefined {
  if (!rejections.some((rejection) => rejection.provider === "atlas")) {
    return "atlas";
  }
  if (!rejections.some((rejection) => rejection.provider === "beacon")) {
    return "beacon";
  }
  return undefined;
}

async function saveDecision(
  dependencies: ShippingDependencies,
  record: StoredShipment,
  rejectionsOnSaveFailure: Refusal[],
): Promise<ServiceResponse | undefined> {
  try {
    await dependencies.repository.save(record.id, record);
  } catch {
    emitAbort(dependencies, record.id, "repository", "repository_failure", rejectionsOnSaveFailure);
    return abortResponse(record.id, "repository", "repository_failure", rejectionsOnSaveFailure);
  }
  return undefined;
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function persistDispatched(
    shipment: StoredShipment,
    provider: Provider,
    bookingId: string,
    nowMs: number,
    rejections: Refusal[],
  ): Promise<ServiceResponse> {
    const dispatched: DispatchedShipment = {
      schemaVersion: 1,
      ...baseFields(shipment),
      state: "dispatched",
      provider,
      bookingId,
      dispatchedAtMs: nowMs,
    };
    const saveFailure = await saveDecision(dependencies, dispatched, rejections);
    if (saveFailure) {
      return saveFailure;
    }
    dependencies.logger.info({
      shipmentId: dispatched.id,
      action: "dispatched",
      provider,
    });
    return { status: 200, body: publicShipment(dispatched) };
  }

  async function persistDeferred(
    shipment: StoredShipment,
    provider: Provider,
    retryAtMs: number,
    rejections: Refusal[],
  ): Promise<ServiceResponse> {
    const deferred: DeferredShipment = {
      schemaVersion: 1,
      ...baseFields(shipment),
      state: "deferred",
      nextProvider: provider,
      retryAtMs,
      rejections: cloneRejections(rejections),
    };
    const saveFailure = await saveDecision(dependencies, deferred, rejections);
    if (saveFailure) {
      return saveFailure;
    }
    dependencies.logger.info({
      shipmentId: deferred.id,
      action: "deferred",
      provider,
      retryAtMs,
      rejections: cloneRejections(rejections),
    });
    return { status: 202, body: publicShipment(deferred) };
  }

  async function persistUnavailable(
    shipment: StoredShipment,
    rejections: Refusal[],
  ): Promise<ServiceResponse> {
    const unavailable: UnavailableShipment = {
      schemaVersion: 1,
      ...baseFields(shipment),
      state: "unavailable",
      rejections: cloneRejections(rejections),
    };
    const saveFailure = await saveDecision(dependencies, unavailable, rejections);
    if (saveFailure) {
      return saveFailure;
    }
    dependencies.logger.info({
      shipmentId: unavailable.id,
      action: "unavailable",
      rejections: cloneRejections(rejections),
    });
    return { status: 422, body: publicShipment(unavailable) };
  }

  async function dispatch(command: Extract<Command, { op: "dispatch" }>, shipment: StoredShipment) {
    if (shipment.state === "dispatched" || shipment.state === "unavailable") {
      return { status: dispatchStatus(shipment), body: publicShipment(shipment) };
    }
    if (shipment.state === "deferred" && command.nowMs < shipment.retryAtMs) {
      return { status: 202, body: publicShipment(shipment) };
    }

    const rejections = shipment.state === "deferred" ? cloneRejections(shipment.rejections) : [];
    let provider: Provider | undefined =
      shipment.state === "deferred" ? shipment.nextProvider : nextUnrefusedProvider(rejections);
    const request = makeProviderRequest(shipment, command.recipient);

    while (provider) {
      if (rejections.some((rejection) => rejection.provider === provider)) {
        provider = nextUnrefusedProvider(rejections);
        continue;
      }

      const outcome = await attemptCarrier(dependencies, provider, request, command.nowMs);
      if (outcome.kind === "confirmed") {
        return persistDispatched(shipment, provider, outcome.bookingId, command.nowMs, rejections);
      }
      if (outcome.kind === "throttled") {
        return persistDeferred(shipment, outcome.provider, outcome.retryAtMs, rejections);
      }
      if (outcome.kind === "aborted") {
        emitAbort(dependencies, shipment.id, outcome.failedAt, outcome.classification, rejections);
        return abortResponse(shipment.id, outcome.failedAt, outcome.classification, rejections);
      }

      rejections.push(outcome.refusal);
      provider = nextUnrefusedProvider(rejections);
    }

    return persistUnavailable(shipment, rejections);
  }

  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      emitAbort(dependencies, command.shipmentId, "repository", "repository_failure", []);
      return abortResponse(command.shipmentId, "repository", "repository_failure", []);
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    // Storage contains the host's queued records, historical dispatched records,
    // or this service's own JSON-compatible records.
    const shipment = value as StoredShipment;
    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }

    return dispatch(command, shipment);
  }

  return { handle };
}
